if(id==='memory'){
 $('#play-area').innerHTML='<div class="gamebox"><p id="memory-hint">빛나는 순서를 기억하세요!</p><div class="memory-grid">'+['♡ 응원','✦ 별','♫ 노래','☾ 밤'].map((v,i)=>'<button data-memory="'+i+'">'+v+'</button>').join('')+'</div>';
 let sequence=[],index=0,timer=0,stage='show',length=3;
 const buttons=[...modal.querySelectorAll('[data-memory]')];
 function next(){audio.fx('item_ready');sequence=Array.from({length},()=>Math.floor(Math.random()*4));index=0;timer=0;stage='show';buttons.forEach(b=>{b.disabled=true;b.classList.remove('lit');});$('#memory-hint').textContent=length+'개 순서를 기억하세요!';}
 buttons.forEach((b,i)=>b.onclick=()=>{if(done||stage!=='input')return;max++;const yes=i===sequence[index];if(yes){score++;index++;}feed(yes?'잘 기억했어요!':'다음 순서에서 다시 도전해요.',yes);$('#mini-status').textContent='정답 '+score+' / '+max;if(!yes||index===sequence.length){if(yes)length=Math.min(6,length+1);stage='wait';timer=0;buttons.forEach(b=>b.disabled=true);}});
 next();onTick=dt=>{timer+=dt;if(stage==='show'){const step=Math.floor(timer/.85);buttons.forEach((b,i)=>b.classList.toggle('lit',step<sequence.length&&i===sequence[step]&&timer%.85<.6));if(step>=sequence.length){stage='input';buttons.forEach(b=>b.disabled=false);$('#memory-hint').textContent='같은 순서로 눌러 주세요!';}}else if(stage==='wait'&&timer>1.1)next();};
}

