  const title=modal.querySelector('#modal-title')?.textContent||'';
  if(title==='크루 합방'&&!modal.querySelector('.crew-modes')){const box=document.createElement('div');box.className='crew-modes gamebox';box.innerHTML=`<b>합방 포맷 선택</b><div class="mode-grid">${COLLAB_MODES.map((m,i)=>`<button class="secondary" data-mode="${i}" aria-pressed="${i===collabMode}">${m}</button>`).join('')}</div><p class="muted">크루원: ${CREW_MEMBERS.join(' · ')}</p>`;modal.querySelector('.buttonrow')?.before(box);box.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{collabMode=+b.dataset.mode;box.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});}
  if(title.includes('기록')&&s.pending&&!modal.querySelector('.result-expression')){const ok=(s.pending.score||0)>=.5;const box=document.createElement('div');box.className='result-expression';box.innerHTML=expressionHTML(ok?2:5,ok?'성공해서 기쁜':'아쉬운');modal.querySelector('.badge')?.after(box);}
