function recordEnding(){const rows=read('fur-rankings-v2')||[];if(!Array.isArray(rows))return;const v=s.endingSnapshot||s;const r={runId:s.runId,name:s.playerName||'이전 플레이어',followers:v.followers,loyal:v.loyal,hype:v.hype,mood:v.mood,day:Math.min(s.day,45),ending:ending(s).id,type:s.phase==='graduated'?'graduate':s.parentRunId?'resumed':'normal'};try{localStorage.setItem('fur-rankings-v2',JSON.stringify([...rows.filter(x=>x.runId!==r.runId),r].slice(-300)));}catch{toast('랭킹 저장에 실패했어요. 저장 파일을 보관해 주세요.');}}
function showEnding(){if(!['end','graduated'].includes(s.phase))return;const e=ending(s),v=s.endingSnapshot||s;s.endingId=e.id;s.endingSnapshot=v;save();recordEnding();let page=0,all=false;
 const prelude=`${esc(s.playerName||'플레이어')}님과 함께한 ${s.log.length}일. 팔로워 ${fmt(v.followers)}명, 화제성 ${v.hype}, 충성도 ${v.loyal}, 기분 ${v.mood}.`;
 const lines=e.id==='happy'?[prelude,'9월 30일, 마지막 방송의 숫자가 확정됐습니다. 약속한 3,000명에 도달했어요.','큐티섹시: “내가 털의 시련을 이겨냈어!”','박재박: “그래 잘했다! 다음 방송도 버블란에서 함께하자.”',v.followers>=3300?'3,300명 이상 달성! 우수 기록을 남겼습니다. 팬들과 더 큰 내일을 준비합니다.':'크루원들의 축하 속에서, 오늘의 마지막 인사는 내일의 약속이 됐습니다.']:e.id==='kyu'?[prelude,'3,000명 약속은 지키지 못해 버블란을 떠나게 됐습니다. 하지만 팬들의 관심과 애정은 높게 남았습니다.','큐티섹시: “수장이 안 불러주면… 내가 수장을 하면 되잖아? 큐한성 크루원 모집합니다!”','팬들: “수장님! 첫 공지는 뭔가요?” 큐티섹시: “어… 일단 전단지부터 같이 접어주세요!”','모집 전단지가 쌓이고 웃음이 번집니다. 엉뚱하지만 씩씩한 새 방송이 시작됩니다.']:e.id==='graduate'?[prelude,`${dateLabel(s.day)}, 체력 0에서 방송을 ${Math.floor(s.zeroEnergyActiveMs/1000)}초 이어갔습니다. 회복할 시간을 갖지 못해 컨디션 유지가 어려워졌어요.`,'큐티섹시: “목표도 중요했지만… 지금은 쉬어야 할 것 같아요. 오늘을 마지막으로 방송을 마무리하려고 해요.”','팬들: “수고했어요. 함께했던 시간은 남아 있어요. 편히 쉬어요.”',s.day<16?'8월의 짧은 도전은 여기서 끝납니다. 다시 시작한다면 8월 16일의 첫 방송으로 돌아갑니다.':'충분히 쉰 뒤 이 날짜를 다시 도전하거나, 8월 16일부터 새 이야기를 시작할 수 있습니다.']: [prelude,'9월 30일, 마지막 방송이 끝났지만 3,000명에 닿지 못했습니다.',e.text,'큐티섹시: “정말 감사했어요. 버블란에서의 시간… 잊지 않을게요.”','박재박: “아쉬운 거지.” 크루원들과 팬들이 조용히 손을 흔듭니다. 이별 뒤에도 함께한 시간은 남아 있습니다.'];
 function paint(){open(`<div class="ending-shell ${e.id}"><div class="ending-heading"><span class="eyebrow">${s.phase==='graduated'?dateLabel(s.day)+' · LAST BROADCAST':'SEPTEMBER 30 · FINAL BROADCAST'}</span><h2 id="modal-title">${e.title}</h2></div><div class="ending-art"><img src="assets/endings/${e.id}.png" alt="${e.title}"></div><section class="ending-story" aria-live="polite">${(all?lines:[lines[page]]).map(t=>`<p>${t}</p>`).join('')}</section><div class="ending-nav"><span>${all?'전체 이야기':`${page+1} / ${lines.length}`}</span><button id="ending-all" class="secondary">전체 이야기</button><button id="ending-next" class="primary">${page<lines.length-1&&!all?'다음 이야기':'정산 보기'}</button><button id="ending-audio" class="secondary">음악 설정</button></div><div class="ending-actions" ${page<lines.length-1&&!all?'hidden':''}><button id="ending-summary" class="primary">${e.id==='graduate'?'지금까지 정산':'8·9월 전체 정산'}</button><button id="ending-ranking" class="secondary">랭킹 보기</button>${e.id==='graduate'&&s.day>=16?'<button id="graduate-retry" class="primary">이 날짜부터 다시 도전</button>':''}<button id="ending-restart" class="secondary">8월 16일부터 다시 시작</button></div></div>`,{locked:true});modal.classList.add('ending-dialog');const im=modal.querySelector('.ending-art img');im.onerror=()=>{im.hidden=true;toast('엔딩 그림을 불러오지 못했지만 이야기는 계속 볼 수 있어요.');};$('#ending-next').onclick=()=>{if(page<lines.length-1&&!all){page++;paint();}else showSummary();};$('#ending-all').onclick=()=>{all=true;paint();};$('#ending-summary').onclick=()=>showSummary();$('#ending-ranking').onclick=()=>showRanking();$('#ending-restart').onclick=()=>restart();if($('#graduate-retry'))$('#graduate-retry').onclick=()=>{recordEnding();s=retryGraduate(s);audio.leaveEnding();save();close();render();toast('휴식 후 이 날짜를 다시 시작합니다. 체력·기분 최소 40.');};$('#ending-audio').onclick=()=>{sound();const back=document.createElement('button');back.className='primary';back.textContent='엔딩으로 돌아가기';back.onclick=paint;modal.append(back);};}
 paint();audio.enterEnding();}
function showSummary(tab='all',onContinue=null){closeDay(s);save();const recordMap=new Map((Array.isArray(s.log)?s.log:[]).map(r=>[r.day,r]));(Array.isArray(s.dailySnapshots)?s.dailySnapshots:[]).forEach(d=>{if(!recordMap.has(d.day))recordMap.set(d.day,{day:d.day,action:d.action||'기록',score:Number(d.score)||0,total:(d.after?.followers??0)-(d.before?.followers??d.after?.followers??0),followers:d.after?.followers??0});});const all=[...recordMap.values()].sort((a,b)=>a.day-b.day).filter(r=>tab==='all'||(tab==='august'?r.day<16:r.day>=16));const snapshots=new Map(s.dailySnapshots.map(r=>[r.day,r]));const first=all[0],last=all.at(-1);const start=first?(snapshots.get(first.day)?.before?.followers??(first.followers-first.total)):s.followers;const end=last?(snapshots.get(last.day)?.after?.followers??last.followers):start;const snaps=all.map(r=>snapshots.get(r.day)).filter(Boolean);const balloonTotal=snaps.reduce((n,r)=>n+(r.after.balloons-(r.before?.balloons??r.after.balloons)),0);const counts={};all.forEach(r=>counts[r.action]=(counts[r.action]||0)+1);const frequent=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];const best=all.slice().sort((a,b)=>b.total-a.total)[0];
 open(`${head('OUR DAYS',tab==='august'?'8월 정산':tab==='september'?'9월 정산':'8·9월 전체 정산')}<div class="summary-tabs">${[['august','8월'],['september','9월'],['all','전체']].map(([k,t])=>`<button class="secondary" data-summary-tab="${k}" aria-pressed="${tab===k}">${t}</button>`).join('')}</div><p>${esc(s.playerName)} · ${all.length}일 기록${s.phase==='graduated'?' · 졸업일까지 부분 정산':''}</p><div class="summary-metrics"><span>팔로워 ${fmt(start)} → ${fmt(end)} (${sign(end-start)})</span><span>최고 ${fmt(Math.max(start,...all.map(r=>r.followers)))}명</span><span>별풍선 +${fmt(balloonTotal)}개</span><span>UP 선발 ${all.filter(r=>r.contest?.qualified).length}회 · 휴식 ${all.filter(r=>r.action==='휴식 · 기획').length}회</span><span>판매 도감 ${s.photoAlbum.length}/10종</span><span>최다 활동 ${esc(frequent?.[0]||'없음')} · 최고의 날 ${best?dateLabel(best.day):'없음'}</span></div><div class="summary-scroll"><table><thead><tr>${['날짜','활동','점수','팔로워 증감/잔액','별풍선','체력','화제성','충성도','즐겨찾기','기분','이벤트'].map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${all.map(r=>{const d=snapshots.get(r.day),v=d?.after;return `<tr><td>${dateLabel(r.day)}</td><td>${esc(r.action)}</td><td>${Math.round(r.score*100)}</td><td>${sign(v&&d.before?v.followers-d.before.followers:r.total)} / ${v?.followers??r.followers}</td><td>${v&&d.before?sign(v.balloons-d.before.balloons):'—'}</td>${['energy','hype','loyal','favorites','mood'].map(k=>`<td>${v?.[k]??'—'}</td>`).join('')}<td>${d?.events.map(e=>esc(e.text)).join(' · ')||'—'}</td></tr>`;}).join('')}</tbody></table></div><p class="muted">— 표시는 이전 버전에 상세 기록이 없거나 해당 이벤트가 없음을 뜻합니다. 도감은 현재까지 누적입니다.</p><div class="buttonrow"><button id="summary-continue" class="primary">${onContinue?'9월 1일로 →':['end','graduated'].includes(s.phase)?'엔딩으로 돌아가기':'게임으로 돌아가기'}</button><button id="summary-rank" class="secondary">랭킹 보기</button><button data-do="export" class="secondary">기록 저장</button></div>`,{locked:!!onContinue});modal.classList.add('summary-dialog');modal.querySelectorAll('[data-summary-tab]').forEach(b=>b.onclick=()=>showSummary(b.dataset.summaryTab,onContinue));$('#summary-continue').onclick=()=>{if(onContinue)onContinue();else if(['end','graduated'].includes(s.phase))showEnding();else close();};$('#summary-rank').onclick=()=>showRanking('normal',()=>showSummary(tab,onContinue));}
function showRanking(type='normal',back=null){const stored=read('fur-rankings-v2');const rows=rankRows((Array.isArray(stored)?stored:[]).filter(r=>r.type===type&&['followers','loyal','hype','mood'].every(k=>Number.isFinite(r[k]))));open(`${head('LOCAL RECORDS','이 기기의 플레이어 랭킹')}<p class="muted">이 브라우저에 저장된 기록입니다. 온라인 전체 순위가 아닙니다.</p><div class="summary-tabs">${[['normal','정상 완주'],['resumed','재개 완주'],['graduate','졸업 기록']].map(([k,t])=>`<button class="secondary" data-rank-tab="${k}" aria-pressed="${type===k}">${t}</button>`).join('')}</div><div class="summary-scroll"><table><thead><tr><th>순위</th><th>플레이어</th><th>팔로워</th><th>충성도</th><th>화제성</th><th>기분</th><th>엔딩</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.rank}</td><td>${esc(r.name)}</td><td>${r.followers}</td><td>${r.loyal}</td><td>${r.hype}</td><td>${r.mood}</td><td>${{happy:'해피',bad:'배드',kyu:'큐한성',graduate:'졸업'}[r.ending]||'—'}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p>아직 기록이 없어요. 엔딩을 보면 등록됩니다.</p>'}</div><button id="rank-back" class="primary">돌아가기</button>`);modal.classList.add('summary-dialog');modal.querySelectorAll('[data-rank-tab]').forEach(b=>b.onclick=()=>showRanking(b.dataset.rankTab,back));$('#rank-back').onclick=()=>{if(back)back();else if(['end','graduated'].includes(s.phase))showEnding();else menu();};}
// One sound per committed UI action; navigation sounds only on keyboard focus changes.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&!b.disabled&&!['up-tap','cheer','jump','left','right'].includes(b.id))audio.fx('select_confirm');});
document.addEventListener('keydown',e=>{if(e.key==='Tab')audio.fx('select_move');});
